CREATE DATABASE IF NOT EXISTS `fat_c1_dido_test_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `fat_c1_dido_test_db`;

-- Table 1: FAT Test Sessions
DROP TABLE IF EXISTS `fat_sessions`;
CREATE TABLE `fat_sessions` (
    `session_id` VARCHAR(32) NOT NULL PRIMARY KEY,
    `project_name` VARCHAR(128) NOT NULL,
    `facility_location` VARCHAR(64) NOT NULL,
    `target_chassis` VARCHAR(16) NOT NULL,
    `panel_id` VARCHAR(16) NOT NULL,
    `test_date` DATE NOT NULL,
    `lead_engineer` VARCHAR(64) NOT NULL,
    `client_rep` VARCHAR(64) NOT NULL,
    `total_channels` INT NOT NULL DEFAULT 192,
    `passed_channels` INT NOT NULL DEFAULT 192,
    `failed_channels` INT NOT NULL DEFAULT 0,
    `avg_latency_ms` DECIMAL(5,2) NOT NULL DEFAULT 28.9,
    `verdict` ENUM('PASS', 'FAIL', 'PENDING') NOT NULL DEFAULT 'PASS',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

VALUES ('FAT-C1-20261008', 'Ingredion Thailand — SPRINT 18K Spray Dryer', 'Kalasin, Thailand', 'Chassis C1', 'MCP-01', '2026-10-08', 'Senior Automation Lead', 'Client E&I Manager', 192, 192, 0, 28.90, 'PASS');

-- Table 2: Chassis C1 Slot Inventory
DROP TABLE IF EXISTS `chassis_c1_slots`;
CREATE TABLE `chassis_c1_slots` (
    `slot_id` VARCHAR(16) NOT NULL PRIMARY KEY,
    `slot_number` INT NOT NULL,
    `module_model` VARCHAR(32) NOT NULL,
    `module_type` VARCHAR(32) NOT NULL,
    `channel_capacity` INT NOT NULL,
    `destination` VARCHAR(64) NOT NULL,
    `health_status` VARCHAR(16) NOT NULL DEFAULT 'OK'
) ENGINE=InnoDB;


-- Table 3: DI/DO FAT Test Verification Results (192 records)
DROP TABLE IF EXISTS `dido_test_results`;
CREATE TABLE `dido_test_results` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `session_id` VARCHAR(32) NOT NULL,
    `test_id` VARCHAR(16) NOT NULL,
    `test_category` ENUM('LOOPBACK_CROSSWIRE', 'DIRECT_DI_SIM') NOT NULL,
    `do_slot` VARCHAR(16) NULL,
    `do_pin` INT NULL,
    `relay_tag` VARCHAR(32) NULL,
    `relay_contact` VARCHAR(16) NULL,
    `jumper_wire_tag` VARCHAR(32) NULL,
    `di_terminal` VARCHAR(32) NOT NULL,
    `di_slot` VARCHAR(16) NOT NULL,
    `di_pin` INT NOT NULL,
    `latency_ms` INT NOT NULL,
    `transition` VARCHAR(16) NOT NULL DEFAULT '0 -> 1 -> 0',
    `verdict` ENUM('PASS', 'FAIL') NOT NULL DEFAULT 'PASS',
    `tested_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    KEY `idx_test_id` (`test_id`),
    KEY `idx_category` (`test_category`),
    KEY `idx_di_slot` (`di_slot`),
    KEY `idx_do_slot` (`do_slot`)
) ENGINE=InnoDB;


-- Verification Query
SELECT test_category, COUNT(*) as total_loops, AVG(latency_ms) as avg_latency, SUM(CASE WHEN verdict='PASS' THEN 1 ELSE 0 END) as passed_loops FROM dido_test_results GROUP BY test_category;